// Groups unread Gmail into conversations (same threadId), separates people from newsletters, flags questions.
const items = $input.all().map(i => i.json);
const noise = /(no-?reply|do-?not-?reply|newsletter|notifications?|mailer|news@|marketing|digest|updates@)/i;
const bulkLabels = ['CATEGORY_PROMOTIONS', 'CATEGORY_UPDATES', 'CATEGORY_SOCIAL', 'CATEGORY_FORUMS'];
const ask = /\?|\b(can|could|would|will) you\b|\bplease\b|\blet me know\b|\bby (mon|tues|wednes|thurs|fri|satur|sun)day\b|\b(asap|urgent|deadline|tomorrow|eod|rsvp)\b/i;
const from = m => String(m.From || m.from?.text || m.from || '');
const name = m => from(m).replace(/\s*<[^>]*>\s*$/, '').replace(/^"|"$/g, '') || from(m);
const subj = m => String(m.Subject || m.subject || '(no subject)');
const isBulk = m => noise.test(from(m)) || (m.labelIds || []).some(l => bulkLabels.includes(l));
const people = items.filter(m => !isBulk(m)), bulk = items.filter(isBulk);
const threads = {};
for (const m of people) (threads[m.threadId || m.id || subj(m)] ||= []).push(m);
const convos = Object.values(threads);
const label = g => [...new Set(g.map(name))].join(', ') + (g.length > 1 ? ` (${g.length} messages)` : '');
const line = g => `- ${subj(g[0])} - ${label(g)}\n  ${String(g[0].snippet || '').slice(0, 160)}`;
const reply = convos.filter(g => g.some(m => ask.test(subj(m) + ' ' + (m.snippet || ''))));
const fyi = convos.filter(g => !reply.includes(g));
const bySender = {};
for (const m of bulk) (bySender[name(m)] ||= []).push(subj(m));
const parts = [`Inbox summary - ${items.length} unread in the last 24h`, ''];
if (!items.length) parts.push('Inbox zero. Nice.');
if (reply.length) parts.push(`May need a reply (${reply.length}):`, ...reply.map(line), '');
if (fyi.length) parts.push(`Other emails from people (${fyi.length}):`, ...fyi.map(line), '');
if (items.length && !convos.length) parts.push('No emails from people.', '');
if (bulk.length) parts.push(`Newsletters / notifications (${bulk.length}):`, ...Object.entries(bySender).sort((a, b) => b[1].length - a[1].length).map(([k, v]) => `- ${k}${v.length > 1 ? ` (${v.length})` : ''}: ${v.slice(0, 3).join('; ')}${v.length > 3 ? ' ...' : ''}`));
return [{ json: { text: parts.join('\n').trim() } }];
